from __future__ import annotations

from pymatgen.symmetry.maggroups import MagneticSpaceGroup
from pymatgen.symmetry.settings import JonesFaithfulTransformation


def _parse_group_number(value):
    """Parse a BNS/OG space-group number given in dotted string form.

    Accepts ``"4.11"`` style strings (as used in magnetic CIF data items)
    as well as integer values and sequences of integers.
    """
    if isinstance(value, str):
        parts = value.split(".")
    else:
        parts = str(value).split(".")
    return [int(part) for part in parts]


class MagneticCifBlock:
    def __init__(self, data):
        self.data = dict(data)


class CifParser:
    """Retained magnetic-CIF operation reader for the task snapshot."""

    def get_magsymops(self, data):
        if isinstance(data, MagneticCifBlock):
            block = data.data
        else:
            block = dict(data)

        if block.get("_space_group_magn.number_BNS"):
            group_id = _parse_group_number(block["_space_group_magn.number_BNS"])
            ops = MagneticSpaceGroup(group_id).symmetry_ops
        elif block.get("_space_group_magn.number_BNS_id"):
            group_id = _parse_group_number(block["_space_group_magn.number_BNS_id"])
            ops = MagneticSpaceGroup(group_id).symmetry_ops
        elif block.get("_space_group_magn.number_OG"):
            og_number = _parse_group_number(block["_space_group_magn.number_OG"])
            ops = MagneticSpaceGroup.from_og(og_number).symmetry_ops
        else:
            raise ValueError("No magnetic symmetry group number found in CIF block.")

        # The tables store operations in the standard BNS setting.  When a
        # producer contributed the record in a different coordinate setting,
        # the CIF block carries the Jones faithful transformation from the BNS
        # setting to that setting.  Apply it so that the returned operations
        # live in the same coordinates as the archived fractional sites.
        transform_string = block.get("_space_group_magn.transform_BNS_Pp_abc")
        if transform_string:
            transform = JonesFaithfulTransformation.from_transformation_string(transform_string)
            ops = [transform.transform_symmop(op) for op in ops]

        return ops

